INSERT INTO `student` VALUES (1,'Ma Thae Su San 1','1CST-1.jpg','1CST-1',1,'14/DaNaPha(N)205726','U San Tun','တော်ရိုးကြီးကျေးရွာ၊ ကျုံ/ရှေ့အုပ်စု၊ ဓနုဖြူမြို့နယ်၊ ဧရာဝတီတိုင်းဒေသကြီး ','09957331533','thaesusan@ucsh.edu.mm','2004-05-20 00:00:00','2024-05-27 00:00:00'),(2,'Ma May Thu Han','1CST-2.jpg','1CST-2',1,'14/KaKhaNa(N)120336','U Han Soe','ပေတောကျေးရွာ၊ ပေတောအုပ်စု၊ ကြံခင်းမြို့နယ်။','09723662377','maythuhan@ucsh.edu.mm','2008-02-20 05:00:00','2024-05-27 00:00:00'),(3,'Ma Ei Ei Khin','1CST-3.jpg','1CST-3',1,'14/HaThaTa(N)376922','U Htay Kyi','ကံလှကျေးရွာ၊ ကံလှအုပ်စု၊ ဟင်္သာတမြို့နယ်၊ ဧရာဝတီတိုင်းဒေသကြီး','09250849931','eieikhin@ucsh.edu.mm','2002-02-20 05:00:00','2024-05-27 00:00:00'),(4,'Ma Thoon Hsu Wati','1CST-5.jpg','1CST-5',1,'12/TaKaNa(N)281082','U Khaing Moe Zaw','အမှတ်(၁၉၄)၊ အ.ထ.က ကျောင်းလမ်း၊ အနော်ရထာရပ်ကွက်၊ ဥက္ကံမြို့၊ တိုက်ကြီးမြို့နယ်၊ ရန်ကုန်တိုင်းဒေသကြီး','09769882007','thoonhsuwati@ucsh.edu.mm','2003-02-20 05:00:00','2024-05-27 00:00:00'),(5,'Ma Jue Jue Wai','1CST-6.jpg','1CST-6',1,'14/HaThaTa(N)362997','U Soe Win','နိဗ္ဗာန်ကျေးရွာ၊ နိဗ္ဗာန်တိုက်နယ်၊ ဟင်္သာတမြို့နယ်၊ ဧရာဝတီတိုင်းဒေသကြီး','09950560690','juejuewai@ucsh.edu.mm','2004-02-20 05:00:00','2024-05-27 00:00:00'),(6,'Mg Soe Myat Aung','1CST-7.jpg','1CST-7',1,'14/HaThaTa(N)403610','U Aung Kyaw Naing','ဥယျာဉ်(၃)လမ်း၊ ကင်းရပ်ကွက်၊ ဟင်္သာတမြို့၊ ဧရာဝတီတိုင်းဒေသကြီး','09695566785','soemyataung@ucsh.edu.mm','2005-02-20 05:00:00','2024-05-27 00:00:00'),(7,'Mg Pyae Ko Ko Maung','1CST-8.jpg','1CST-8',1,'14/HaThaTa(N)390175','U Nay Win','အမှတ်(၉၅)၊ မာလာလမ်း၊ ဥယျာဉ်မြောက်ရပ်ကွက်၊ ဟင်္သာတမြို့၊ ဧရာဝတီတိုင်းဒေသကြီး','09681088624','pyaekokomaung@ucsh.edu.mm','2006-02-20 05:00:00','2024-05-27 00:00:00'),(8,'Mg Thar Htet','1CST-9.jpg','1CST-9',1,'14/HaThaTa(N)363168','U Thaung Aye','နတ်ဝင်ကုန်းရွာ၊ ရိုးကြီးအုပ်စု၊ ဟင်္သာတမြို့နယ်၊ ဧရာဝတီတိုင်းဒေသကြီး','09698453897','tharhtet@ucsh.edu.mm','2007-02-20 05:00:00','2024-05-27 00:00:00'),(9,'Mg Zaw Lwin Aung','1CST-10.jpg','1CST-10',1,'14/HAThaTa(N)359208','U 